    commandId?: string;
    operation: string;
    actor: Actor;
    /**
     * The permission preset the policy engine applied
     */
    preset?: string;
    projectId?: string;
    /**
     * ok, approval (stored as an approval), denied (policy), expired (approval nobody decided), or the problem slug of a failed attempt
     */
