    runId?: string;
    kind: string;
    kindVersion: string;
    jobKind: JobKind;
    gpu?: boolean;
    memoryGb?: number;
    state: 'waiting' | 'paused' | 'running' | 'stopping';
    priority: number;
    /**
     * The project's queue priority (budgets.queuePriority): the first sort key, before priority
     */
